#!/usr/bin/env python3
"""Turns the phone pages in components/vellum_core/web into C++ source.

Run after editing a page:
  python3 tools/embed_page.py
The host tests check that the generated file matches the pages.
"""
import pathlib

root = pathlib.Path(__file__).resolve().parent.parent
pages = [("kUploadPage", "upload.html"), ("kSetupPage", "setup.html")]
out = root / "components/vellum_core/src/upload_page.cpp"
parts = [
    "// Generated by tools/embed_page.py from web/*.html. Do not edit.\n"
    '#include "vellum/upload_page.h"\n\n'
    "namespace vellum {\n\n"
]
total = 0
for name, file in pages:
    page = (root / "components/vellum_core/web" / file).read_text(encoding="utf-8")
    if ')page"' in page:
        raise SystemExit(f'{file} contains the raw-string delimiter )page"')
    parts.append(f'const char {name}[] = R"page(' + page + ')page";\n\n')
    parts.append(f"const unsigned {name}Size = sizeof({name}) - 1;\n\n")
    total += len(page.encode())
parts.append("}  // namespace vellum\n")
out.write_text("".join(parts), encoding="utf-8")
print(f"wrote {out.relative_to(root)} ({total} bytes of pages)")
